from collections import deque

class Solution:
    def minDays(self, n: int) -> int:
        dist = {n: 0}
        q = deque([n])
        while q:
            c = q.popleft()
            if c == 0:
                return dist[c]
            for nxt in ([c - 1] + ([c // 2] if c % 2 == 0 else []) +
                        ([2 * (c // 3)] if c % 3 == 0 else [])):
                if nxt not in dist:
                    dist[nxt] = dist[c] + 1
                    q.append(nxt)
        return -1

