#include <unordered_map>
#include <queue>
using namespace std;

class Solution {
public:
    int minDays(int n) {
        unordered_map<long long,int> dist;
        queue<long long> q;
        dist[n] = 0;
        q.push(n);
        while (!q.empty()) {
            long long c = q.front(); q.pop();
            if (c == 0) return dist[c];
            vector<long long> nxt{c - 1};
            if (c % 2 == 0) nxt.push_back(c / 2);
            if (c % 3 == 0) nxt.push_back(2 * (c / 3));
            for (long long x : nxt)
                if (!dist.count(x)) { dist[x] = dist[c] + 1; q.push(x); }
        }
        return -1;
    }
};

