import java.util.*;

class Solution {
    public int minDays(int n) {
        Map<Long,Integer> dist = new HashMap<>();
        Deque<Long> q = new ArrayDeque<>();
        dist.put((long)n, 0);
        q.add((long)n);
        while (!q.isEmpty()) {
            long c = q.poll();
            if (c == 0) return dist.get(c);
            List<Long> nxt = new ArrayList<>();
            nxt.add(c - 1);
            if (c % 2 == 0) nxt.add(c / 2);
            if (c % 3 == 0) nxt.add(2 * (c / 3));
            for (long x : nxt)
                if (!dist.containsKey(x)) { dist.put(x, dist.get(c) + 1); q.add(x); }
        }
        return -1;
    }
}

