var minDays = function(n) {
    const dist = new Map([[n, 0]]);
    const q = [n];
    let head = 0;
    while (head < q.length) {
        const c = q[head++];
        if (c === 0) return dist.get(c);
        const nxt = [c - 1];
        if (c % 2 === 0) nxt.push(c / 2);
        if (c % 3 === 0) nxt.push(2 * Math.floor(c / 3));
        for (const x of nxt)
            if (!dist.has(x)) { dist.set(x, dist.get(c) + 1); q.push(x); }
    }
    return -1;
};

