from functools import lru_cache

class Solution:
    def minDays(self, n: int) -> int:
        @lru_cache(maxsize=None)
        def f(m):
            if m <= 2:
                return m
            return min(m % 2 + 1 + f(m // 2), m % 3 + 1 + f(m // 3))
        return f(n)

