class Solution {
    unordered_map<long long,int> memo;
    int f(long long m) {
        if (m <= 2) return (int)m;
        auto it = memo.find(m);
        if (it != memo.end()) return it->second;
        int res = min(m % 2 + 1 + f(m / 2), m % 3 + 1 + f(m / 3));
        memo[m] = res;
        return res;
    }
