import java.util.HashMap;
import java.util.Map;

class Solution {
    private final Map<Long,Integer> memo = new HashMap<>();

    private int f(long m) {
        if (m <= 2) return (int)m;
        Integer cached = memo.get(m);
        if (cached != null) return cached;
        int res = Math.min((int)(m % 2) + 1 + f(m / 2),
                          (int)(m % 3) + 1 + f(m / 3));
        memo.put(m, res);
        return res;
    }

    public int minDays(int n) {
        memo.clear();
        return f(n);
    }
}

